<script setup>
import {ref,computed,onMounted} from 'vue';import {withBase} from 'vitepress';import catalog from '../../../../data/catalog.json';
const school=ref(catalog.schools.find(s=>s.id==='cn-uibe')?.id||catalog.schools[0].id),data=ref([]),error=ref('');const selected=computed(()=>data.value.find(s=>s.schoolId===school.value));
async function load(){error.value='';try{const r=await fetch(withBase('/data/timelines.json'));if(!r.ok)throw Error();data.value=await r.json()}catch{error.value='时间线加载失败，请重试。'}}onMounted(load);
const stages=[['2026 秋','大三上','了解本校推免条件、目标项目与科研准备','比较考试科目与跨专业要求','核对先修课、语言及 GRE / GMAT 要求'],['2027 春夏','大三下 / 暑期','准备夏令营、提前选拔及面试材料','按统考与专业课系统复习','准备考试、推荐信、文书与实践经历'],['2027 秋','大四上','关注预推免、正式推免与录取确认','核对招生目录、网报及网上确认','按各项目轮次递交；留意更早批次'],['2027 冬 — 2028 春','申请与考核','关注录取后的材料及资格要求','初试、成绩、复试与调剂','后续轮次、面试及录取结果比较'],['2028 春夏','毕业与入学','完成毕业和入学手续','确认录取与毕业手续','确认入学、签证、住宿及必要费用']];
</script>
<template><div class="app-page"><header class="page-intro"><div class="eyebrow">APPLICATION ROADMAP</div><h1>把准备放在截止日期之前。</h1><p>先看升学准备节奏，再看学校实际发布的日程。历史日期保持原样，未向后平移。</p></header><section id="preparation"><div class="section-heading"><h2>2028 入学 · 三条路径准备节奏</h2><span class="badge">规划示意 · 非官方截止日</span></div><div class="roadmap-scroll"><table class="roadmap"><thead><tr><th>阶段</th><th>推免</th><th>统考</th><th>境外 / 申请制</th></tr></thead><tbody><tr v-for="s in stages"><th>{{s[0]}}<small>{{s[1]}}</small></th><td>{{s[2]}}</td><td>{{s[3]}}</td><td>{{s[4]}}</td></tr></tbody></table></div></section><section class="school-timeline"><div class="section-heading"><div><div class="eyebrow">DATES FROM THE REPORTS</div><h2>逐校申请与考试节点</h2></div><label class="select-field"><span>选择大学</span><select v-model="school"><option v-for="s in catalog.schools" :value="s.id">{{s.name}}</option></select></label></div><div class="notice"><span>注意届别</span><p>以下原文来自各校报告第 4 章。已公布、历史参考、待核验与不适用的状态均保留；请结合对应项目正文核对。</p></div><div v-if="error" role="alert">{{error}} <button @click="load">重试</button></div><div v-else-if="!selected" role="status">正在读取时间线…</div><template v-else><div class="timeline-school-title"><h3>{{selected.school}}</h3><a :href="withBase(selected.path)">查看原报告 ↗</a></div><div class="vp-doc timeline-content" v-html="selected.html"></div></template></section></div></template>
